import React, { useRef, useEffect } from 'react';

export default function MeshSphere({ size = 300, speed = 0.4, distort = 0.5 }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width  = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const cx = size / 2, cy = size / 2, r = size * 0.34;

    // Smooth morph — returns x,y on the blob surface
    const getPoint = (angle, scale = 1, phase = 0) => {
      const s = t.current * 0.18; // very slow
      const w = 1
        + Math.sin(angle * 2.0 + s * 0.85 + phase) * 0.040 * distort
        + Math.cos(angle * 3.1 + s * 0.55 + phase) * 0.026 * distort
        + Math.sin(angle * 4.7 + s * 1.05 + phase) * 0.016 * distort
        + Math.cos(angle * 1.4 + s * 0.38 + phase) * 0.020 * distort
        + Math.sin(angle * 6.3 + s * 0.72 + phase) * 0.009 * distort;
      return {
        x: cx + Math.cos(angle) * r * scale * w,
        y: cy + Math.sin(angle) * r * scale * w,
      };
    };

    const draw = () => {
      t.current += 0.003 * speed;
      ctx.clearRect(0, 0, size, size);

      const N = 360;

      // ── Helper: draw a smooth closed gradient filled shape ──
      const drawBlob = (scale, phase, fillFn) => {
        ctx.beginPath();
        for (let i = 0; i <= N; i++) {
          const p = getPoint((i / N) * Math.PI * 2, scale, phase);
          i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y);
        }
        ctx.closePath();
        ctx.fillStyle = fillFn();
        ctx.fill();
      };

      // ── 1. Multi-layer outer glow — NO hard edge, feathered ─
      // We paint concentric blobs from largest to smallest,
      // each very transparent, so edges dissolve completely
      const glowLayers = 6;
      for (let i = glowLayers; i >= 1; i--) {
        const scale = 1 + i * 0.16;
        const a     = (0.04 - i * 0.006);
        const hue   = 220 + i * 20 + Math.sin(t.current * 0.12 + i) * 18;
        drawBlob(scale, i * 0.35, () => {
          const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r * scale);
          g.addColorStop(0,    `hsla(${hue}, 55%, 82%, 0)`);
          g.addColorStop(0.55, `hsla(${hue}, 55%, 82%, 0)`);
          g.addColorStop(0.8,  `hsla(${hue}, 55%, 82%, ${a * 0.5})`);
          g.addColorStop(1,    `hsla(${hue}, 58%, 80%, ${a})`);
          return g;
        });
      }

      // ── 2. Main body — clip so fill stays inside ────────────
      ctx.save();
      ctx.beginPath();
      for (let i = 0; i <= N; i++) {
        const p = getPoint((i / N) * Math.PI * 2, 1, 0);
        i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y);
      }
      ctx.closePath();

      // Feathered outer edge — paint a soft-edge mask by drawing
      // the same shape twice: once filled, once with soft erase
      ctx.save();
      ctx.clip();

      // Glass base
      const base = ctx.createRadialGradient(
        cx - r * 0.06, cy - r * 0.08, r * 0.05,
        cx + r * 0.12, cy + r * 0.14, r * 1.08
      );
      base.addColorStop(0,    'rgba(248,246,255, 0.94)');
      base.addColorStop(0.30, 'rgba(232,236,255, 0.86)');
      base.addColorStop(0.60, 'rgba(210,222,252, 0.78)');
      base.addColorStop(0.88, 'rgba(190,208,248, 0.72)');
      base.addColorStop(1,    'rgba(175,198,244, 0.68)');
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, size, size);

      // ── Iridescent pools ─────────────────────────────────────
      const pools = [
        { ax:0.24, ay:0.16, bx:0.18, by:0.10, br:0.62, h:182, s:58, l:72, A:0.50, sp:0.36 },
        { ax:-0.18,ay:-0.08,bx:-0.14,by:0.07, br:0.56, h:222, s:50, l:68, A:0.42, sp:0.28 },
        { ax:0.10, ay:-0.20,bx:-0.08,by:-0.18,br:0.50, h:262, s:46, l:72, A:0.36, sp:0.40 },
        { ax:-0.06,ay:0.26, bx:0.12, by:0.20, br:0.44, h: 32, s:62, l:80, A:0.26, sp:0.24 },
        { ax:0.28, ay:-0.06,bx:0.20, by:-0.14,br:0.40, h:308, s:44, l:76, A:0.22, sp:0.33 },
      ];

      pools.forEach(p => {
        const s  = t.current * p.sp;
        const px = cx + (Math.sin(s) * r * p.ax + Math.cos(s * 0.7) * r * p.bx);
        const py = cy + (Math.cos(s * 0.85) * r * p.ay + Math.sin(s * 1.1) * r * p.by);
        const hue = p.h + Math.sin(t.current * 0.12 + p.sp) * 16;
        const g = ctx.createRadialGradient(px, py, 0, px, py, r * p.br);
        g.addColorStop(0,    `hsla(${hue}, ${p.s}%, ${p.l}%, ${p.A})`);
        g.addColorStop(0.45, `hsla(${hue + 14}, ${p.s}%, ${p.l + 4}%, ${p.A * 0.35})`);
        g.addColorStop(1,    'transparent');
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, size, size);
      });

      // Bright lens — white glass centre
      const lens = ctx.createRadialGradient(
        cx - r * 0.09, cy - r * 0.13, 0,
        cx - r * 0.04, cy - r * 0.08, r * 0.75
      );
      lens.addColorStop(0,    'rgba(255,255,255, 0.90)');
      lens.addColorStop(0.15, 'rgba(255,255,255, 0.55)');
      lens.addColorStop(0.40, 'rgba(255,255,255, 0.16)');
      lens.addColorStop(0.72, 'rgba(255,255,255, 0.03)');
      lens.addColorStop(1,    'transparent');
      ctx.fillStyle = lens;
      ctx.fillRect(0, 0, size, size);

      // Subtle depth edge
      const edge = ctx.createRadialGradient(cx, cy, r * 0.52, cx, cy, r);
      edge.addColorStop(0,   'transparent');
      edge.addColorStop(0.78,'rgba(150,175,230,0.05)');
      edge.addColorStop(1,   'rgba(120,150,220,0.18)');
      ctx.fillStyle = edge;
      ctx.fillRect(0, 0, size, size);

      ctx.restore(); // unclip

      // ── 3. Rainbow rim — using compositing so it's INSIDE ───
      // This is the key: we paint the rim with destination-atop
      // so it only shows where the sphere already has pixels
      ctx.globalCompositeOperation = 'source-atop';
      const rimN = 120;
      for (let i = 0; i < rimN; i++) {
        const a1  = (i / rimN) * Math.PI * 2 + t.current * 0.10;
        const a2  = ((i + 2.0) / rimN) * Math.PI * 2 + t.current * 0.10;
        const hue = (i / rimN) * 360;
        // Fade rim alpha where the sphere is bright (top-left) vs dark (bottom-right)
        const edgeAlpha = 0.18 + Math.sin(a1 + Math.PI * 0.75) * 0.14;
        ctx.beginPath();
        // Draw slightly inside so no hard outer edge
        const rRim = r * 0.92;
        ctx.arc(cx, cy, rRim, a1, a2);
        ctx.strokeStyle = `hsla(${hue}, 72%, 78%, ${edgeAlpha})`;
        ctx.lineWidth = r * 0.10; // wide, soft strokes
        ctx.stroke();
      }
      ctx.globalCompositeOperation = 'source-over';

      ctx.restore(); // outer save

      // ── 4. Dissolving outer edge — paint OVER with transparent ─
      // This softens any remaining hard edge from the clip
      ctx.save();
      ctx.beginPath();
      for (let i = 0; i <= N; i++) {
        const p = getPoint((i / N) * Math.PI * 2, 1, 0);
        i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y);
      }
      ctx.closePath();
      // Erase the outer ring by painting inward transparency
      ctx.globalCompositeOperation = 'destination-out';
      const fade = ctx.createRadialGradient(cx, cy, r * 0.88, cx, cy, r * 1.02);
      fade.addColorStop(0,   'rgba(0,0,0,0)');
      fade.addColorStop(0.6, 'rgba(0,0,0,0)');
      fade.addColorStop(1,   'rgba(0,0,0,0.35)');
      ctx.fillStyle = fade;
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
      ctx.restore();

      // ── 5. Soft shadow beneath ──────────────────────────────
      const sh = ctx.createRadialGradient(cx, cy + r * 0.82, 0, cx, cy + r * 0.9, r * 0.50);
      sh.addColorStop(0, 'rgba(140,155,210,0.10)');
      sh.addColorStop(1, 'transparent');
      ctx.beginPath();
      ctx.ellipse(cx, cy + r * 0.90, r * 0.48, r * 0.08, 0, 0, Math.PI * 2);
      ctx.fillStyle = sh;
      ctx.fill();

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, speed, distort]);

  return (
    <canvas ref={canvasRef} style={{ display:'block', width:`${size}px`, height:`${size}px` }} />
  );
}
